import type { MetadataRoute } from "next";

import { site } from "@/config/site";

/**
 * Web app manifest (served at /manifest.webmanifest). Icons are generated by
 * `scripts/brand/build-icons.mjs` from docs/design/brand (DESIGN-SYSTEM §2.2).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: `${site.brand.name} — ${site.brand.tagline}`,
    short_name: site.brand.name,
    description: site.brand.description,
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: site.themeColor,
    theme_color: site.themeColor,
    lang: site.locale,
    dir: "ltr",
    categories: ["shopping", "auto"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
